update horse_visual_asset_requirements set canvas_width=1496,canvas_height=1051 where body_template_key in('qh_mare_master_01','qh_stallion_master_01');
alter table horse_visual_asset_requirements drop constraint if exists horse_visual_asset_requirements_status_check;alter table horse_visual_asset_requirements add constraint horse_visual_asset_requirements_status_check check(status in('missing','review','needs_revision','approved','production'));
alter table horse_visual_assets add column if not exists version integer not null default 1,add column if not exists supersedes_asset_id uuid references horse_visual_assets(id),add column if not exists validation jsonb not null default '{}';
create table if not exists horse_visual_production_history(id uuid primary key default gen_random_uuid(),requirement_id uuid not null references horse_visual_asset_requirements(id),asset_id uuid not null references horse_visual_assets(id),action text not null check(action in('promoted','rolled_back','removed')),actor_id uuid references stables(id),notes text not null default '',created_at timestamptz not null default now());alter table horse_visual_production_history enable row level security;create policy "admins read production history" on horse_visual_production_history for select using(exists(select 1 from stables where id=auth.uid()and is_admin));
create or replace function public.admin_register_visual_asset(p_requirement uuid,p_asset_key text,p_image_url text,p_width integer,p_height integer,p_file_type text,p_file_size integer)returns uuid language plpgsql security definer set search_path=public as $$declare r horse_visual_asset_requirements;a uuid;m horse_visual_assets;prior uuid;next_version integer;begin perform require_admin();select * into r from horse_visual_asset_requirements where id=p_requirement for update;if not found then raise exception 'Visual requirement not found';end if;if lower(p_file_type)not in('image/png','image/webp')then raise exception 'Asset must be PNG or WebP';end if;if p_file_size<=0 or p_file_size>10485760 then raise exception 'Asset must be under 10 MB';end if;if p_width<>r.canvas_width or p_height<>r.canvas_height then raise exception 'Asset canvas must be exactly % x %',r.canvas_width,r.canvas_height;end if;select * into m from horse_visual_assets where asset_key=r.body_template_key;select r.asset_id,coalesce(max(version),0)+1 into prior,next_version from horse_visual_assets where body_template_key=r.body_template_key and asset_key like left(p_asset_key,100)||'%'group by r.asset_id;next_version:=coalesce(next_version,1);insert into horse_visual_assets(asset_key,asset_type,breed,sex,phenotype_key,marking_key,leg_position,image_url,z_index,status,active,review_notes,created_by,body_template_key,canvas_width,canvas_height,version,supersedes_asset_id,validation)values(left(p_asset_key||'_v'||next_version,120),r.category,m.breed,m.sex,case when r.category in('base_coat','modifier','dapple','mane','tail')then r.trait_key end,case when r.category in('face_marking','leg_marking','pattern','pinto_pattern','leopard_complex')then r.trait_key end,case r.anatomical_position when'LF'then'left_front'when'RF'then'right_front'when'LH'then'left_hind'when'RH'then'right_hind'end,left(p_image_url,2048),50,'pending',false,'Human-supplied asset awaiting Owner review',auth.uid(),r.body_template_key,p_width,p_height,next_version,prior,jsonb_build_object('file_type',p_file_type,'file_size',p_file_size,'canvas_valid',true,'transparency_client_validated',true))returning id into a;update horse_visual_asset_requirements set asset_id=a,status='review',notes='',updated_at=now()where id=r.id;return a;end$$;
create or replace function public.admin_review_visual_asset(p_requirement uuid,p_action text,p_notes text default '')returns void language plpgsql security definer set search_path=public as $$declare r horse_visual_asset_requirements;a horse_visual_assets;begin perform require_super_admin();select * into r from horse_visual_asset_requirements where id=p_requirement for update;select * into a from horse_visual_assets where id=r.asset_id for update;if a.id is null then raise exception 'No uploaded asset is mapped to this requirement';end if;if p_action='approve'then update horse_visual_assets set status='approved',active=false,approved_by=auth.uid(),approved_at=now(),review_notes=left(p_notes,500)where id=a.id;update horse_visual_asset_requirements set status='approved',notes=left(p_notes,500),updated_at=now()where id=r.id;elsif p_action in('reject','needs_revision')then update horse_visual_assets set status=case when p_action='reject'then'rejected'else'pending'end,active=false,review_notes=left(p_notes,500)where id=a.id;update horse_visual_asset_requirements set status=case when p_action='reject'then'missing'else'needs_revision'end,notes=left(p_notes,500),updated_at=now()where id=r.id;else raise exception 'Choose Approve, Reject, or Needs Revision';end if;end$$;
create or replace function public.admin_promote_visual_asset(p_requirement uuid,p_notes text default '')returns void language plpgsql security definer set search_path=public as $$declare r horse_visual_asset_requirements;a horse_visual_assets;begin perform require_super_admin();select * into r from horse_visual_asset_requirements where id=p_requirement for update;select * into a from horse_visual_assets where id=r.asset_id for update;if r.status<>'approved'or a.status<>'approved'or a.body_template_key<>r.body_template_key or a.canvas_width<>r.canvas_width or a.canvas_height<>r.canvas_height then raise exception 'Only the current approved exact-master version can enter Production';end if;update horse_visual_assets set active=false where body_template_key=r.body_template_key and asset_type=r.category and coalesce(phenotype_key,marking_key,'')=coalesce(a.phenotype_key,a.marking_key,'')and id<>a.id;update horse_visual_assets set active=true where id=a.id;update horse_visual_asset_requirements set status='production',notes=left(p_notes,500),updated_at=now()where id=r.id;insert into horse_visual_production_history(requirement_id,asset_id,action,actor_id,notes)values(r.id,a.id,'promoted',auth.uid(),left(p_notes,500));end$$;
create or replace function public.admin_rollback_visual_asset(p_requirement uuid,p_asset uuid,p_notes text default '')returns void language plpgsql security definer set search_path=public as $$declare r horse_visual_asset_requirements;a horse_visual_assets;begin perform require_super_admin();select * into r from horse_visual_asset_requirements where id=p_requirement for update;select * into a from horse_visual_assets where id=p_asset;if a.id is null or a.body_template_key<>r.body_template_key or a.status<>'approved'or a.canvas_width<>r.canvas_width or a.canvas_height<>r.canvas_height then raise exception 'Rollback target must be an approved exact-master version';end if;update horse_visual_asset_requirements set asset_id=a.id,status='approved',notes=left(p_notes,500),updated_at=now()where id=r.id;insert into horse_visual_production_history(requirement_id,asset_id,action,actor_id,notes)values(r.id,a.id,'rolled_back',auth.uid(),left(p_notes,500));end$$;
create or replace function public.admin_visual_workspace()returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;begin perform require_admin();select coalesce(jsonb_agg(item order by item->>'master',item->>'category',item->>'display_name'),'[]')into result from(select jsonb_build_object('requirement_id',r.id,'master',r.body_template_key,'master_url',m.image_url,'breed',m.breed,'sex',m.sex,'category',r.category,'trait_key',r.trait_key,'display_name',t.display_name,'limb',r.anatomical_position,'variant',r.variant,'status',r.status,'notes',r.notes,'width',r.canvas_width,'height',r.canvas_height,'asset_id',a.id,'asset_key',a.asset_key,'asset_url',a.image_url,'version',a.version,'uploaded_at',a.created_at,'approved_at',a.approved_at,'history',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'key',v.asset_key,'url',v.image_url,'version',v.version,'status',v.status,'notes',v.review_notes,'uploaded_at',v.created_at,'approved_at',v.approved_at)order by v.version desc)from horse_visual_assets v where v.body_template_key=r.body_template_key and v.asset_type=r.category and coalesce(v.phenotype_key,v.marking_key,'')=coalesce(a.phenotype_key,a.marking_key,r.trait_key,'')and coalesce(v.leg_position,'')=coalesce(a.leg_position,case r.anatomical_position when'LF'then'left_front'when'RF'then'right_front'when'LH'then'left_hind'when'RH'then'right_hind'end,'')),'[]'::jsonb))item from horse_visual_asset_requirements r join horse_visual_assets m on m.asset_key=r.body_template_key join equine_visual_taxonomy t on t.category=r.category and t.trait_key=r.trait_key left join horse_visual_assets a on a.id=r.asset_id)s;return result;end$$;
revoke all on function admin_review_visual_asset(uuid,text,text),admin_promote_visual_asset(uuid,text),admin_rollback_visual_asset(uuid,uuid,text),admin_visual_workspace()from public;grant execute on function admin_review_visual_asset(uuid,text,text),admin_promote_visual_asset(uuid,text),admin_rollback_visual_asset(uuid,uuid,text),admin_visual_workspace()to authenticated;
